import{_ as t,o,c as d,ag as a}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"TableDetail — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/patterns/TableDetail/TableDetail.figma-notes.md","filePath":"public/demos/src/patterns/TableDetail/TableDetail.figma-notes.md"}'),i={name:"public/demos/src/patterns/TableDetail/TableDetail.figma-notes.md"};function n(s,e,r,l,c,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="tabledetail-—-figma-notes" tabindex="-1">TableDetail — Figma Notes <a class="header-anchor" href="#tabledetail-—-figma-notes" aria-label="Permalink to &quot;TableDetail — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Pattern <strong>Built:</strong> 2026-08-25 (Seating Planner module, wave 4) <strong>Files:</strong> <code>TableDetail.css</code>, <code>TableDetail.html</code>, <code>TableDetail.figma.ts</code>, <code>TableDetail.figma-notes.md</code><strong>Composes:</strong> AttendeeCard (one per seat), TableType (tier pill), Button (via AttendeeCard&#39;s Assign) <strong>JS:</strong> none</p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI — Design System)</li><li><strong>Page:</strong> Seat Planner (<code>3087:5050</code>)</li><li><strong>Component set:</strong> <code>3475:94010</code></li></ul><h2 id="variant-matrix-8-variants" tabindex="-1">Variant matrix (8 variants) <a class="header-anchor" href="#variant-matrix-8-variants" aria-label="Permalink to &quot;Variant matrix (8 variants)&quot;">​</a></h2><p>Axes are <strong>Type × Tier × Device</strong>. Tier is single-valued (<code>Pattern</code>). Device is a media query. <strong>Type produces no CSS at all</strong> — see below. So 8 Figma variants collapse to <strong>one</strong> CSS class plus a media query.</p><table tabindex="0"><thead><tr><th>Type</th><th>Device</th><th>Node</th><th>Figma size</th><th>CSS</th></tr></thead><tbody><tr><td>Default</td><td>Desktop</td><td><code>3475:94006</code></td><td>320×648</td><td><code>.table-detail</code></td></tr><tr><td>2 Roles</td><td>Desktop</td><td><code>3475:94007</code></td><td>320×698</td><td><code>.table-detail</code></td></tr><tr><td>All Roles</td><td>Desktop</td><td><code>3475:94009</code></td><td>320×698</td><td><code>.table-detail</code></td></tr><tr><td>Full</td><td>Desktop</td><td><code>3475:94008</code></td><td>320×698</td><td><code>.table-detail</code></td></tr><tr><td>Default</td><td>Mobile</td><td><code>3488:201546</code></td><td>320×550</td><td><code>@media (max-width: 767px)</code></td></tr><tr><td>2 Roles</td><td>Mobile</td><td><code>3488:201570</code></td><td>320×591</td><td>↑</td></tr><tr><td>All Roles</td><td>Mobile</td><td><code>3488:201601</code></td><td>320×601</td><td>↑</td></tr><tr><td>Full</td><td>Mobile</td><td><code>3488:201641</code></td><td>320×607</td><td>↑</td></tr></tbody></table><p>Width is <strong>320px at every variant</strong>, bound to <code>--ai-size-6</code> — a fixed rail, not a fluid panel.</p><h3 id="the-whole-type-axis-is-data-not-css" tabindex="-1">The whole Type axis is data, not CSS <a class="header-anchor" href="#the-whole-type-axis-is-data-not-css" aria-label="Permalink to &quot;The whole Type axis is data, not CSS&quot;">​</a></h3><p>Type names the count of <strong>distinct roles seated</strong>, and that is all that changes:</p><table tabindex="0"><thead><tr><th>Type</th><th>Legend</th><th>Seats filled</th></tr></thead><tbody><tr><td>Default</td><td><strong>absent entirely</strong></td><td>0</td></tr><tr><td>2 Roles</td><td>2 items</td><td>2</td></tr><tr><td>All Roles</td><td>5 items</td><td>7</td></tr><tr><td>Full</td><td>5 items</td><td>10</td></tr></tbody></table><p>All of that is markup the caller supplies, so there are deliberately <strong>no Type modifiers</strong> — the same finding as TableCard. The 50px height difference between Default and the rest is just the legend (29px) plus the list gap (8px) plus filled cards being 50px against Empty&#39;s 48px.</p><p><strong>The legend is derived, not stored.</strong> It lists the distinct roles actually seated, which is why Default has none at all rather than an empty container.</p><h2 id="height-fills-the-column-list-scrolls" tabindex="-1">Height: fills the column, list scrolls <a class="header-anchor" href="#height-fills-the-column-list-scrolls" aria-label="Permalink to &quot;Height: fills the column, list scrolls&quot;">​</a></h2><p>Figma pins the desktop panel at <code>h-[698px]</code>, which has no token and is simply how tall it drew ten seats. <strong>Designer&#39;s call 2026-08-25: the panel fills its column and the seat list scrolls inside a fixed header</strong>, so a twenty-seat table works and the header stays put.</p><p>That is three things working together, and all three are needed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.table-detail        block-size: 100%; overflow: hidden</span></span>
<span class="line"><span>.table-detail__header  flex-shrink: 0</span></span>
<span class="line"><span>.table-detail__list    flex: 1; min-block-size: 0; overflow-y: auto</span></span></code></pre></div><p><code>min-block-size: 0</code> is the non-obvious one — a flex item refuses to shrink below its content without it, so the panel would grow instead of the list scrolling. <code>overflow: hidden</code> on the panel keeps the scrolling list clipped inside the 16px radius. Verified: with the panel bounded to 560px, the list reports <code>scrollHeight</code> 647 against <code>clientHeight</code> 485.</p><p>The mobile variants carry <strong>no fixed height at all</strong> in Figma, so nothing extra is needed there.</p><h2 id="device-mobile-deltas" tabindex="-1">Device=Mobile deltas <a class="header-anchor" href="#device-mobile-deltas" aria-label="Permalink to &quot;Device=Mobile deltas&quot;">​</a></h2><p>All four mobile variants <strong>drop the panel header entirely</strong> — no table name, seated count, sponsor or tier pill. Verified on <code>3488:201546</code> and <code>3488:201601</code>, so it is deliberate rather than one variant being out of step.</p><table tabindex="0"><thead><tr><th>Property</th><th>Desktop</th><th>Mobile</th></tr></thead><tbody><tr><td><code>__header</code></td><td>present</td><td><strong><code>display: none</code></strong></td></tr><tr><td><code>__list</code> <code>padding</code></td><td><code>--ai-spacing-5</code> inline + block-end, no block-start</td><td><code>--ai-spacing-3</code> (8px) all round</td></tr><tr><td><code>__seats</code> <code>gap</code></td><td><code>--ai-spacing-3</code> (8px)</td><td><code>--ai-spacing-2</code> (6px)</td></tr></tbody></table><p>The header is hidden rather than made optional, at the designer&#39;s direction — the mobile screen supplies the table name in its own sheet chrome. <strong>See the accessibility note below.</strong></p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code></td><td>panel <code>background-color</code></td><td></td></tr><tr><td><code>--ai-border-secondary</code></td><td>panel <code>border-color</code>, legend <code>border-color</code></td><td></td></tr><tr><td><code>--ai-radius-lg</code></td><td>panel <code>border-radius</code> (16px)</td><td></td></tr><tr><td><code>light/shadow-xxs</code> → <code>--ai-shadow-xxs</code></td><td>panel <code>box-shadow</code></td><td></td></tr><tr><td><code>--ai-size-6</code></td><td>panel <code>inline-size</code> (320px)</td><td>fixed at both breakpoints</td></tr><tr><td><code>--ai-spacing-5</code></td><td>header <code>padding</code> + <code>gap</code>, list <code>padding</code> (desktop)</td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>header-row <code>gap</code>, meta <code>gap</code>, list <code>gap</code>, seats <code>gap</code>, legend <code>padding</code>, swatch size, mobile list <code>padding</code></td><td></td></tr><tr><td><code>--ai-spacing-1</code></td><td>titles <code>gap</code>, legend-item <code>gap</code></td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td>sponsor <code>gap</code>, mobile seats <code>gap</code></td><td></td></tr><tr><td><code>--ai-spacing-0-5</code></td><td>legend <code>gap</code></td><td>CSS leads Figma — see below</td></tr><tr><td><code>--ai-font-title</code></td><td>name, meta, legend</td><td></td></tr><tr><td><code>--ai-font-fixed-md</code></td><td>table name (18px)</td><td></td></tr><tr><td><code>--ai-font-fixed-2xs</code></td><td>meta / seated count (12px)</td><td></td></tr><tr><td><code>--ai-font-fixed-4xs</code></td><td>legend labels (11px)</td><td></td></tr><tr><td><code>--ai-font-bold</code> / <code>-medium</code></td><td>name / meta + legend</td><td></td></tr><tr><td><code>--ai-font-body</code></td><td>sponsor name</td><td>inconsistent with TableCard — see below</td></tr><tr><td><code>--ai-leading-xs</code></td><td>sponsor <code>line-height</code> (16px)</td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code> / <code>--ai-text-secondary</code></td><td>name / meta / legend</td><td></td></tr><tr><td><code>--ai-icon-size-sm</code></td><td>handshake icon (16px)</td><td></td></tr><tr><td><code>--ai-icon-secondary</code></td><td>handshake icon colour</td><td><strong>differs from TableCard</strong> — see below</td></tr><tr><td><code>--ai-surface-minimal</code></td><td>legend <code>background-color</code></td><td></td></tr><tr><td><code>--ai-radius-md</code></td><td>legend <code>border-radius</code> (8px)</td><td></td></tr><tr><td><code>--ai-radius-xs</code></td><td>legend swatch <code>border-radius</code> (2px)</td><td>the token added 2026-08-25</td></tr><tr><td><code>--sp-host</code> / <code>-vip</code> / <code>-speaker</code> / <code>-sponsor</code> / <code>-attendee</code></td><td>legend swatches</td><td>all five roles</td></tr></tbody></table><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td>panel <code>h-[698px]</code></td><td><strong>Dropped for <code>block-size: 100%</code></strong> — see the height section. 698px has no token and is just ten seats&#39; worth of height.</td></tr><tr><td>sponsor row <code>h-[22px]</code></td><td><strong>Left to content (16px)</strong> — see below.</td></tr><tr><td><code>panel-header</code> <code>border-0</code> with <code>--ai-border-secondary</code> still set</td><td><strong>No border drawn.</strong> A zero-width border with a colour left on it; the rendered design shows no divider under the header, so none is implemented. If a divider is wanted it needs a width in Figma first.</td></tr><tr><td>3px <code>Ellipse</code> separator</td><td><strong>A middot character</strong>, matching the identical separator in AttendeeCard. Avoids an off-scale 3px dimension with no token.</td></tr><tr><td><code>Orange/600</code> (<code>#ea580c</code>) in the subtree&#39;s variable list</td><td><strong>Not a gap.</strong> It appears in <code>get_variable_defs</code> but <strong>zero times</strong> in the panel&#39;s design context, so nothing being built uses it. Likely bound on a hidden layer or in another Seating Planner mode.</td></tr></tbody></table><h3 id="the-sponsor-row-s-22px-height-is-flagged-not-inlined" tabindex="-1">The sponsor row&#39;s 22px height is flagged, not inlined <a class="header-anchor" href="#the-sponsor-row-s-22px-height-is-flagged-not-inlined" aria-label="Permalink to &quot;The sponsor row&#39;s 22px height is flagged, not inlined&quot;">​</a></h3><p>Figma pins the sponsor row at <code>h-[22px]</code>. In TableCard the identical 22px is <em>derivable</em> — exactly <code>--ai-spacing-2</code> (6px) of padding-top plus a 16px icon — so it was safely omitted. <strong>Here there is no padding</strong>, so 22px is genuinely off-scale and unbound (the nearest steps are 16px and 24px).</p><p>Rather than inline a raw 22px, the row is left to its content, which measures 16px. The visible consequence is the header rendering <strong>73px against Figma&#39;s 80px</strong>. Everything inside is pixel-correct; only that 6px of slack in the sponsor row differs. <strong>Worth either binding a token in Figma or confirming the row should just hug its content.</strong></p><h2 id="scrollbar" tabindex="-1">Scrollbar <a class="header-anchor" href="#scrollbar" aria-label="Permalink to &quot;Scrollbar&quot;">​</a></h2><p>The seat list carries a <strong>transparent track with a thin <code>--ai-surface-secondary</code> thumb</strong>, per the designer 2026-08-25 — matching <code>.chat-sidebar__sections</code>, the existing precedent for this treatment.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scrollbar-color: var(--ai-surface-secondary) transparent;</span></span>
<span class="line"><span>scrollbar-width: thin;</span></span></code></pre></div><p>Plus <code>::-webkit-scrollbar</code> / <code>-track</code> / <code>-thumb</code> rules for older WebKit, using <code>--ai-spacing-2</code> (6px) where the ChatSidebar precedent hardcodes <code>6px</code>.</p><p><strong>Measured gutter: 11px, not 6px.</strong> Once <code>scrollbar-width: thin</code> is declared, Chrome 121+ honours the standard property and ignores the <code>::-webkit-scrollbar</code> width — so 11px <em>is</em> the browser&#39;s &quot;thin&quot;, and the webkit width is effectively dead code kept only for older WebKit. The same is true of the ChatSidebar precedent, where the 6px is equally inert in a current browser. Getting a literal 6px in Chrome would mean dropping <code>scrollbar-width: thin</code>, which costs Firefox its thin scrollbar — so this is standards-first by choice, not by accident.</p><p>Side benefit: <code>thin</code> reclaims 4px of gutter over the default <code>auto</code>, which widened the seat cards from 271px to 275px and gave the single-row legend more slack.</p><h2 id="one-place-the-css-leads-figma" tabindex="-1">One place the CSS leads Figma <a class="header-anchor" href="#one-place-the-css-leads-figma" aria-label="Permalink to &quot;One place the CSS leads Figma&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Property</th><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td><code>__legend</code></td><td><code>row-gap</code></td><td><code>4px</code></td><td><strong><code>--ai-spacing-0-5</code></strong> (2px)</td></tr><tr><td><code>__legend</code></td><td><code>column-gap</code></td><td><code>8px</code></td><td><code>--ai-spacing-3</code> (8px) — Figma&#39;s, unchanged</td></tr></tbody></table><p>Only the <strong>row</strong> gap was tightened (designer, 2026-08-25). Figma binds a split gap on this container — 4px row, 8px column, both via <code>--ai-spacing-3</code>.</p><p><strong>The row gap does visible work here, because the five-role legend wraps.</strong> Figma fits it on one row: its items total 240px and its content box is 272px, so 240 plus four 8px gaps fills it exactly. Our text metrics come out slightly narrower (237px) but the content box is narrower still (257px after the panel border, list padding and the scrollbar gutter), so the row needs 269px and <strong>wraps to two</strong>. Measured:</p><table tabindex="0"><thead><tr><th>Type</th><th>Legend rows</th><th>Legend height</th></tr></thead><tbody><tr><td>2 Roles</td><td>1</td><td>32px</td></tr><tr><td>All Roles / Full</td><td><strong>2</strong></td><td>48px</td></tr></tbody></table><p>So the five-role legend is one row in Figma and two in the browser, with the two rows 2px apart. That is a <strong>12px shortfall against one-row parity</strong> — worth knowing, since closing it would need either a narrower column gap (an earlier attempt at a uniform 2px did fit on one row, but that is not what was wanted), shorter role labels, or a wider panel. <code>flex-wrap</code> is deliberate, so wrapping is a graceful outcome rather than an overflow.</p><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><p>The same contract as the rest of the module:</p><ul><li><strong>Presentational only, no JS.</strong> The seat rows are AttendeeCards — drop targets whose <code>--dragged-over</code> the parent module toggles. Nothing here drags.</li><li>The <strong>guest list is a Figma <code>slot</code></strong>, so the seat rows are content the caller supplies. The legend is likewise caller-supplied, derived from whoever knows which roles are seated.</li><li>Delete, reorder and Assign are AttendeeCard&#39;s own controls; this pattern adds no controls of its own beyond the tier pill, which is not interactive.</li></ul><h2 id="cross-component-findings" tabindex="-1">Cross-component findings <a class="header-anchor" href="#cross-component-findings" aria-label="Permalink to &quot;Cross-component findings&quot;">​</a></h2><ul><li><strong>The handshake icon&#39;s colour differs between the two components.</strong> TableDetail binds <code>--ai-icon-secondary</code> (<code>#64748b</code>), TableCard binds <code>--ai-icon-contrast</code> (<code>#94a3b8</code>). Both were resolved with <code>get_variable_defs</code> on the icon node itself (<code>3472:85943</code> here) because design context hides the colour inside an SVG asset. Built as drawn in each; <strong>worth deciding whether the same icon in the same role should differ.</strong></li><li><strong>The sponsor name&#39;s font-family differs too</strong> — <code>--ai-font-body</code> here, <code>--ai-font-title</code> in TableCard. Both resolve to Inter so it is visually a no-op, but the binding is inconsistent.</li><li><strong>AttendeeCard&#39;s seat badge has drifted.</strong> Figma now renders it at <code>--ai-font-fixed-6xs</code> (9px); the component is <code>--ai-font-fixed-5xs</code> (10px). The designer&#39;s call 2026-08-25 was that <strong>the component stays the source of truth</strong> and Figma should follow, so AttendeeCard was left alone. Recorded here so a future audit does not &quot;fix&quot; it backwards. Every other AttendeeCard divergence seen in this panel (seat box 18→16px, meta gap, accent wrapper, action padding, reorder height) matches what <code>AttendeeCard.figma-notes.md</code> already documents.</li><li><strong><code>Left-Footer-Area</code> is reused as a frame name</strong> for the meta line here, having meant the count-plus-badge group in TableCard. Figma layer-naming noise; worth renaming.</li><li><strong><code>guest-list</code> is a <code>slot</code> on three variants and a plain <code>frame</code> on Type=Default</strong> — the same container modelled two ways.</li></ul><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li><strong>Hiding the header on mobile takes the table name and seated count out of the accessibility tree</strong>, not just out of view. That is only correct because the mobile screen supplies them in its own sheet chrome — designer-confirmed 2026-08-25. If that chrome ever goes away, this needs revisiting, because a screen-reader user would have a list of seats with nothing naming the table. The panel carries an <code>aria-label</code> naming the table as partial mitigation.</li><li>The <strong>legend is real text</strong>, not colour alone — each role is named beside its swatch, so the colour coding is never the only carrier of meaning.</li><li>The seat list is a scroll container and is keyboard-scrollable; every control inside it is a real <code>&lt;button&gt;</code> from AttendeeCard.</li><li>The panel is a <code>&lt;section&gt;</code> with an <code>aria-label</code>; the table name is an <code>&lt;h3&gt;</code>, nesting under the demo&#39;s <code>&lt;h2&gt;</code> section headings.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>get_design_context</code> on the panel root returns ~61KB</strong> and expands all ten AttendeeCard instances rather than collapsing them to Code Connect snippets. Fetch the sub-frames (<code>panel-header</code>, <code>legend</code>) individually, or extract the shell lines with a script — reading the whole thing is wasteful.</li><li><strong>The first AttendeeCard instance is 280px wide where the other nine are 288</strong> (and 280 vs 304 on mobile). It carries <code>size-full</code>, so this is Figma frame noise rather than a width override — our card is fluid and fills the row either way.</li><li><strong>No hover, focus, pressed or disabled variants</strong> exist in the set, and no dark-mode variant. The <code>--sp-*</code> role colours are <strong>not</strong> theme-aware, so the legend swatches will not adapt under <code>[data-theme=&quot;dark&quot;]</code>.</li></ul><hr><h2 id="responsive-container-queries-2026-08-27" tabindex="-1">Responsive: container queries (2026-08-27) <a class="header-anchor" href="#responsive-container-queries-2026-08-27" aria-label="Permalink to &quot;Responsive: container queries (2026-08-27)&quot;">​</a></h2><p><strong>Keys on <code>cs-page</code>, NOT a self-container.</strong> This panel is a fixed <strong>320px</strong> at both breakpoints, which is under 767 — so <code>container-type</code> on this root plus a <code>max-width: 767px</code> self-query would fire permanently, on desktop included, and the header would never render. Its mobile deltas are about the screen being narrow, not the panel.</p><p>Separately, when the panel is used <strong>inline inside TableListing&#39;s grid</strong> on the Seating Planner, its header is hidden by placement (<code>.table-listing__grid &gt; .table-detail</code>) rather than by width — see that template&#39;s notes. Placement is the real condition: the header is redundant exactly when a card above supplies the name and count.</p><p>Rationale and the decision rule live in <strong>CLAUDE.md §4a</strong>. The short version: a docked SidebarMenu shrinks the CC content column with no window resize, so a viewport query cannot see the real available width — measured 820px of column at a 2239px viewport, with no query firing.</p>`,56)])])}const b=t(i,[["render",n]]);export{g as __pageData,b as default};
